<script setup lang="ts">
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue'
import axios from 'axios'
const props=defineProps<{options:{genres:any[],channels?:any[]}}>()
const base='/api/v1/admin/ads',headers=()=>({Authorization:'Bearer '+(localStorage.getItem('admin_token')||'cookie-session')})
const data=ref<any>(null),loading=ref(false),error=ref(''),days=ref('30'),from=ref(''),to=ref(''),query=ref(''),picked=ref<any>(null),suggestions=ref<any[]>([]),kind=ref('all'),genre=ref(''),channel=ref(''),sort=ref('views'),page=ref(1),tab=ref('videos'),segmentPage=ref(1)
const applied=ref(''),appliedChannel=ref('');let appliedParams=''
const fingerprint=()=>JSON.stringify([days.value,from.value,to.value,query.value,picked.value?.id,kind.value,genre.value,channel.value,sort.value])
const dirty=computed(()=>!!data.value&&applied.value!==fingerprint())
const tabs=[['videos','Фильмы и серии'],['genres','Жанры'],['channels','Каналы']]
let generation=0,searchGeneration=0,timer:ReturnType<typeof setTimeout>|null=null,disposed=false
const number=(n:number)=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(n)
const time=(n:number|null)=>n==null?'Нет данных':n>=3600?number(n/3600)+' ч':n>=60?number(n/60)+' мин':number(n)+' с'
function params(){const p=new URLSearchParams({days:days.value==='custom'?'30':days.value,page:String(page.value),page_size:'20',sort:sort.value,kind:kind.value});if(picked.value){p.set('target_id',picked.value.id);p.set('kind',picked.value.kind)}else if(query.value.trim())p.set('q',query.value.trim());if(genre.value)p.set('genre_id',genre.value);if(channel.value)p.set('channel_id',channel.value);if(days.value==='custom'){if(from.value)p.set('date_from',new Date(from.value).toISOString());if(to.value)p.set('date_to',new Date(to.value).toISOString())}return p}
async function load(newFilters=false){const g=++generation;loading.value=true;error.value='';try{if((newFilters||!appliedParams)&&days.value==='custom'&&(!from.value||!to.value))throw new Error('Укажите начало и конец периода');if(newFilters||!appliedParams){appliedParams=params().toString();applied.value=fingerprint();appliedChannel.value=channel.value}const requestParams=new URLSearchParams(appliedParams);requestParams.set('page',String(page.value));const r=await axios.get(base+'/traffic-analytics?'+requestParams,{headers:headers()});if(g===generation&&!disposed)data.value=r.data}catch(e:any){if(g===generation&&!disposed){data.value=null;error.value=typeof e.response?.data?.detail==='string'?e.response.data.detail:e.message||'Не удалось загрузить статистику'}}finally{if(g===generation&&!disposed)loading.value=false}}
function apply(){page.value=1;segmentPage.value=1;void load(true)}
function reset(){query.value='';picked.value=null;suggestions.value=[];kind.value='all';genre.value='';channel.value='';sort.value='views';days.value='30';from.value='';to.value='';apply()}
async function search(){const g=++searchGeneration;if(picked.value||query.value.trim().length<2){suggestions.value=[];return}try{const r=await axios.get(base+'/traffic-analytics/videos?q='+encodeURIComponent(query.value.trim()),{headers:headers()});if(g===searchGeneration&&!disposed)suggestions.value=r.data.items}catch{if(g===searchGeneration)suggestions.value=[]}}
function choose(v:any){searchGeneration++;picked.value=v;query.value=v.title;suggestions.value=[];apply()}
function clearFilm(){picked.value=null;query.value='';suggestions.value=[];apply()}
watch(query,()=>{searchGeneration++;suggestions.value=[];if(picked.value&&query.value!==picked.value.title)picked.value=null;if(timer)clearTimeout(timer);timer=setTimeout(()=>{void search()},300)})
watch(tab,()=>{segmentPage.value=1})
onMounted(()=>void load(true));onBeforeUnmount(()=>{disposed=true;generation++;searchGeneration++;if(timer)clearTimeout(timer)})
</script>
<template>
 <section class="traffic" aria-labelledby="traffic-title" :aria-busy="loading">
  <header><p class="eyebrow">Аудитория KINOSOTA</p><h2 id="traffic-title">Аналитика трафика и популярных видео</h2><p class="muted">Реальные просмотры основного видео. Запуски авторизации и реклама не повышают популярность.</p></header>
  <form class="filters" @submit.prevent="apply">
   <div class="film-search"><label for="analytics-film">Найти фильм или серию</label><input id="analytics-film" type="search" v-model="query" maxlength="200" placeholder="Начните вводить название" autocomplete="off" /><ul v-if="suggestions.length" aria-label="Найденные видео" class="suggestions"><li v-for="v in suggestions" :key="v.kind+v.id"><button type="button" @click="choose(v)">{{v.title}} <small>{{v.kind==='movie'?'Фильм':'Серия'}} · {{v.id.slice(0,8)}}</small></button></li></ul><button v-if="picked" type="button" class="text-button" @click="clearFilm">Убрать выбор: {{picked.title}}</button></div>
   <label>Период<select v-model="days"><option value="7">7 дней</option><option value="30">30 дней</option><option value="90">90 дней</option><option value="365">Год</option><option value="custom">Свой период</option></select></label>
   <label>Тип контента<select v-model="kind" :disabled="!!picked"><option value="all">Фильмы и серии</option><option value="movie">Только фильмы</option><option value="episode">Только серии</option></select></label>
   <label>Жанр<select v-model="genre"><option value="">Все жанры</option><option v-for="g in props.options.genres" :key="g.id" :value="String(g.id)">{{g.name}}</option></select></label>
   <label>Канал источника<select v-model="channel"><option value="">Все каналы</option><option value="unknown">Канал не определён</option><option v-for="c in props.options.channels||[]" :key="c.id" :value="c.id">{{c.name}}{{c.active?'':' · выключен'}}</option></select></label>
   <label>Сортировать по<select v-model="sort"><option value="views">Просмотрам ↓</option><option value="watch_time">Времени просмотра ↓</option><option value="unique_viewers">Уникальным зрителям ↓</option></select></label>
   <template v-if="days==='custom'"><label>Начало · время вашего браузера<input type="datetime-local" v-model="from" required /></label><label>Конец, не включая · время вашего браузера<input type="datetime-local" v-model="to" required /></label></template>
   <div class="actions"><button class="primary" :disabled="loading">Применить фильтры</button><button type="button" @click="reset" :disabled="loading">Сбросить</button></div>
  </form>
  <p v-if="dirty" role="status" class="empty">Фильтры изменены. Нажмите «Применить фильтры», чтобы обновить показатели. До этого показана предыдущая выборка.</p>
  <p v-if="loading" class="loading" role="status">Загружаем сводку и рейтинги…</p>
  <div v-if="error" class="error" role="alert"><p>{{error}}</p><button type="button" @click="load(true)">Повторить</button></div>
  <template v-if="data&&!loading">
   <p class="muted scope">Показаны применённые фильтры. Дни и часы: Europe/Kyiv.</p>
   <dl class="kpis"><div><dt>Просмотры</dt><dd>{{number(data.summary.views)}}</dd><small>Фильмы: {{number(data.summary.movie_views)}} · серии: {{number(data.summary.episode_views)}}</small></div><div><dt>Уникальные зрители</dt><dd>{{number(data.summary.unique_viewers)}}</dd><small>Не складываются между сегментами</small></div><div><dt>Время просмотра</dt><dd>{{time(data.summary.watch_time_sec)}}</dd><small>Среднее за сеанс: {{time(data.summary.average_watch_sec)}}</small></div><div><dt>Просмотрено видео</dt><dd>{{number(data.summary.videos_watched)}}</dd><small>Удержание: {{data.summary.retention_pct==null?'Нет данных':number(data.summary.retention_pct)+'%'}} · выборка {{number(data.summary.retention_sample)}}</small></div></dl>
   <p v-if="!data.summary.views" class="empty">За этот период и с этими фильтрами фактических просмотров не найдено. Попробуйте расширить период или сбросить фильтры.</p>
   <div class="view-tabs" role="group" aria-label="Разрез статистики"><button v-for="t in tabs" :key="t[0]" type="button" :aria-pressed="tab===t[0]" @click="tab=t[0]">{{t[1]}}</button></div>
   <section v-if="tab==='videos'" aria-label="Рейтинг видео">
    <h3>Рейтинг видео</h3><p class="muted">От большего к меньшему по выбранной метрике. Всего видео в рейтинге: {{data.top_total}}.</p>
    <div class="table-scroll"><table><caption class="sr-only">Видео по фактическим просмотрам</caption><thead><tr><th scope="col">Видео</th><th scope="col">Просмотры</th><th scope="col">Зрители</th><th scope="col">Время</th><th scope="col">Удержание / выборка</th><th scope="col">Реклама сейчас</th></tr></thead><tbody><tr v-for="v in data.top" :key="v.kind+v.id"><th scope="row"><button type="button" class="text-button" @click="choose(v)">{{v.title}}</button><small class="block">{{v.kind==='movie'?'Фильм':'Серия'}}{{v.available?'':' · сейчас недоступно'}}</small></th><td>{{number(v.views)}}</td><td>{{number(v.unique_viewers)}}</td><td>{{time(v.watch_time_sec)}}</td><td>{{v.retention_pct==null?'Нет данных':number(v.retention_pct)+'%'}} / {{v.retention_sample}}</td><td>{{v.ads.join(', ')||'Нет'}}</td></tr><tr v-if="!data.top.length"><td colspan="6">Видео не найдены</td></tr></tbody></table></div>
    <nav class="pagination" aria-label="Страницы рейтинга"><button type="button" :disabled="page<=1" @click="page--;load()">Назад</button><span>{{page}} / {{Math.max(1,Math.ceil(data.top_total/20))}}</span><button type="button" :disabled="page*20>=data.top_total" @click="page++;load()">Далее</button></nav>
    <details><summary>Запуски авторизации отдельно от просмотров</summary><p>Всего запусков: {{appliedChannel?'Не рассчитываются с фильтром канала':data.summary.authorized_starts}}. Это разрешения на запуск, а не доказанные просмотры.</p><ul><li v-for="v in data.top" :key="v.id">{{v.title}}: {{appliedChannel?'Нет данных по каналу':v.authorized_starts}}</li></ul></details>
   </section>
   <section v-else aria-label="Рейтинг сегментов"><h3>{{tab==='genres'?'Какие жанры смотрят больше':'Из каких каналов смотрят больше'}}</h3><p class="muted" v-if="tab==='genres'">Один фильм может иметь несколько жанров. Его просмотр учитывается в каждом: сумма долей может превышать 100%.</p><p class="muted" v-else>Канал известен для {{data.summary.channel_attributed_views}} из {{data.summary.views}} просмотров. Без привязки: {{data.summary.channel_unknown_views}}. Старым просмотрам канал не назначается задним числом.</p>
    <div class="table-scroll"><table><caption class="sr-only">Сегменты по просмотрам</caption><thead><tr><th scope="col">{{tab==='genres'?'Жанр':'Канал'}}</th><th scope="col">Просмотры ↓</th><th scope="col">Доля просмотров</th><th scope="col">Зрители</th><th scope="col">Время</th></tr></thead><tbody><tr v-for="s in data[tab].slice((segmentPage-1)*20,segmentPage*20)" :key="s.id"><th scope="row">{{s.name}}</th><td>{{number(s.views)}}</td><td>{{number(s.share_pct)}}%</td><td>{{number(s.unique_viewers)}}</td><td>{{time(s.watch_time_sec)}}</td></tr><tr v-if="!data[tab].length"><td colspan="5">Нет наблюдений в выбранном разрезе</td></tr></tbody></table></div>
    <nav class="pagination" aria-label="Страницы сегментов"><button type="button" :disabled="segmentPage<=1" @click="segmentPage--">Назад</button><span>{{segmentPage}} / {{Math.max(1,Math.ceil(data[tab].length/20))}}</span><button type="button" :disabled="segmentPage*20>=data[tab].length" @click="segmentPage++">Далее</button></nav>
   </section>
   <details class="details"><summary>Динамика по дням</summary><div class="table-scroll"><table><thead><tr><th>Дата · Europe/Kyiv</th><th>Просмотры</th><th>Зрители</th><th>Время</th></tr></thead><tbody><tr v-for="d in data.daily" :key="d.date"><th>{{d.date}}</th><td>{{d.views}}</td><td>{{d.unique_viewers}}</td><td>{{time(d.watch_time_sec)}}</td></tr></tbody></table></div></details>
   <details class="details"><summary>Время суток, дни недели, устройства и переходы</summary><div class="extras"><section><h3>Часы · Europe/Kyiv</h3><ul><li v-for="h in data.hours" :key="h.hour">{{String(h.hour).padStart(2,'0')}}:00 — {{h.views}}</li></ul></section><section><h3>Дни недели</h3><ul><li v-for="w in data.weekdays" :key="w.weekday">{{['Пн','Вт','Ср','Чт','Пт','Сб','Вс'][w.weekday]}} — {{w.views}}</li></ul><h3>Устройства</h3><ul><li v-for="d in data.devices" :key="d.name">{{d.name}} — {{d.views}}</li></ul><h3>Переходы</h3><ul><li v-for="r in data.referrers" :key="r.name">{{r.name}} — {{r.views}}</li></ul></section></div></details>
   <details class="details"><summary>Как считаются показатели</summary><ul><li v-for="n in data.notes" :key="n">{{n}}</li></ul></details>
  </template>
 </section>
</template>
<style scoped>
.traffic{color:var(--ui-text);font-size:14px;line-height:1.5}.traffic *{box-sizing:border-box;min-width:0}.traffic h2{font-size:24px;line-height:32px;margin:4px 0 8px;text-wrap:balance}.traffic h3{font-size:18px;line-height:28px;margin:24px 0 8px}.eyebrow,.muted,small{color:var(--ui-muted)}.eyebrow{margin:0}.filters{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;padding:24px 0;border-bottom:1px solid var(--ui-border)}label{display:flex;flex-direction:column;gap:8px}button,input,select{font:inherit;border:1px solid var(--ui-border);border-radius:8px;background:var(--ui-surface);color:var(--ui-text);padding:8px 12px;min-height:44px}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:2px solid var(--ui-primary);outline-offset:3px}.primary{background:var(--ui-primary);color:var(--ui-on-primary,#fff)}.actions{display:flex;align-items:end;gap:8px;flex-wrap:wrap}.film-search{position:relative}.film-search>input{width:100%;margin-top:8px}.suggestions{position:absolute;z-index:5;top:76px;left:0;right:0;max-height:320px;overflow:auto;padding:8px;margin:0;list-style:none;border:1px solid var(--ui-border);border-radius:8px;background:var(--ui-surface)}.suggestions button{text-align:left;width:100%;border:0}.suggestions small,.block{display:block}.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:24px 0}.kpis>div{padding:16px;border:1px solid var(--ui-border);border-radius:12px;background:var(--ui-surface)}dt{color:var(--ui-muted)}dd{font-size:30px;line-height:36px;font-weight:600;margin:8px 0;font-variant-numeric:tabular-nums}.view-tabs,.pagination{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:24px 0 16px}.view-tabs [aria-pressed=true]{border-color:var(--ui-primary);color:var(--ui-primary)}.table-scroll{width:100%;overflow:auto;border:1px solid var(--ui-border);border-radius:8px}.traffic table{width:100%;min-width:800px;border-collapse:collapse}th,td{text-align:left;padding:12px 16px;border-bottom:1px solid var(--ui-border);font-variant-numeric:tabular-nums}thead th{color:var(--ui-muted);white-space:nowrap}.traffic tbody th{min-width:220px;font-weight:400}tbody tr:last-child>*{border-bottom:0}.text-button{border:0;padding:0;text-align:left;background:transparent;min-height:44px;color:var(--ui-primary);overflow-wrap:anywhere}details{padding:16px 0;border-top:1px solid var(--ui-border)}summary{cursor:pointer;min-height:44px;display:list-item;padding:8px 0}.extras{display:grid;grid-template-columns:1fr 1fr;gap:24px}.error,.empty,.loading{padding:16px;border:1px solid var(--ui-border);border-radius:8px}.error{color:var(--ui-danger)}.sr-only{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:900px){.filters{grid-template-columns:repeat(2,minmax(0,1fr))}.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:540px){.filters,.extras,.kpis{grid-template-columns:1fr}.filters{padding:16px 0}.traffic h2{font-size:20px;line-height:28px}.kpis{gap:8px}.kpis>div{padding:12px}.traffic .view-tabs button{flex:1}th,td{padding:12px}}
</style>
